def coloring_scheme(x, y):
    """C(x, y) = 3 * (x mod 3) + (y mod 3) + 1"""
    return 3 * (x % 3) + (y % 3) + 1

# Define the 3x3 window (indices 0, 1, 2)
window = [(i, j) for i in range(3) for j in range(3)]

all_checks_passed = True

# Iterate over all points (x, y) in the window
for x, y in window:
    color_xy = coloring_scheme(x, y)

    # Check all potential neighbors (a, b) in the window
    for a, b in window:
        # Must be distinct points
        if (x, y) == (a, b):
            continue

        # Check for adjacency: |x-a| <= 1 and |y-b| <= 1
        dx = abs(x - a)
        dy = abs(y - b)

        if dx <= 1 and dy <= 1:
            # They are neighbors
            color_ab = coloring_scheme(a, b)

            if color_xy == color_ab:
                print("Failure found: {}".format(
                    "(x={}, y={}) and (a={}, b={}) are neighbors but have the same color ({})".format(
                        x, y, a, b, color_xy
                    )
                ))
                all_checks_passed = False
                # Stop checking as soon as one failure is found
                break
    if not all_checks_passed:
        break

if all_checks_passed:
    print("Verification successful: All adjacent pairs within the 3x3 fundamental domain have different colors according to the scheme C(x, y) = 3*(x mod 3) + (y mod 3) + 1.")
